const isNum=v=>typeof v==="number"&&isFinite(v);
const FDASH="\u2014",FMINUS="\u2212",FMON=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const ffmt=v=>{if(!isNum(v))return FDASH;const t=Math.abs(v).toLocaleString("en-IN",{maximumFractionDigits:2});return(v<0&&/[1-9]/.test(t)?FMINUS:"")+t};
/* P/E, P/B and EV/EBITDA divide a share price or an enterprise value, which are above zero, so a value of exactly 0 cannot be a real ratio: it is how the source
   reports a figure it does not have. It is shown as a dash and sorted with the missing values. ROE, ROCE and ROA can genuinely be 0 and keep it. */
const NOZERO={pe:1,pb:1,ev_ebitda:1};
function fval(x,k){const v=x?x[k]:null;return NOZERO[k]&&v===0?null:v}
/* ROE is not comparable when shareholders' equity is negative: a negative P/B says so directly, and a loss (negative P/E) together with a positive ROE can only come
   from negative equity (or from the two figures covering different periods). Such an ROE is never treated as a high return: it is left out of the ROE filter,
   sorted after every comparable ROE, and flagged in the table. The value itself is still shown, as published. */
function froeBad(x){return!!x&&isNum(x.roe)&&((isNum(x.pb)&&x.pb<0)||(isNum(x.pe)&&x.pe<0&&x.roe>0))}
const FROE_FLAG='<span class="fs-flag" title="Not comparable: negative shareholders\u2019 equity, or a loss alongside a positive ROE">\u2020<span class="mk-vh"> not comparable</span></span>';
/* "2026-10-28" (or a timestamp starting with it) -> "28 Oct 2026"; anything else is shown as given */
function fday(d){const m=/^(\d{4})-(\d{2})-(\d{2})/.exec(String(d==null?"":d));return m&&+m[2]>=1&&+m[2]<=12?m[3]+" "+FMON[+m[2]-1]+" "+m[1]:(d==null?FDASH:String(d))}
const FNUM=/^(?:\d+(?:\.\d+)?|\.\d+)$/;
const FCOLS=[["symbol","Stock"],["company_name","Company"],["sector","Sector"],["pe","P/E"],["pb","P/B"],["roe","ROE %"],["roce","ROCE %"],["roa","ROA %"],["ev_ebitda","EV/EBITDA"]];
const TEXTK={symbol:1,company_name:1,sector:1};
const fel=i=>document.getElementById(i);
function fread(id,label){const el=fel(id);if(!el)return{on:false};const t=String(el.value==null?"":el.value).trim();el.removeAttribute("aria-invalid");
 if(t==="")return{on:false};
 if(!FNUM.test(t)||!isFinite(+t)){el.setAttribute("aria-invalid","true");return{err:label+": enter a number of 0 or more, such as 12 or 12.5, or leave it empty."}}
 return{on:true,v:+t}}
function criteria(){const errs=[],c={};
 const take=(k,id,label)=>{const r=fread(id,label);if(r.err)errs.push(r.err);c[k]=r.on?r.v:null};
 c.peMode=(fel("fsPeMode")||{}).value||"any";
 if(c.peMode==="negative"){c.peMin=null;c.peMax=null}else{take("peMin","fsPeMin","P/E minimum");take("peMax","fsPeMax","P/E maximum")}
 c.pbMode=(fel("fsPbMode")||{}).value||"any";
 if(c.pbMode==="negative"){c.pbMin=null;c.pbMax=null}else{take("pbMin","fsPbMin","P/B minimum");take("pbMax","fsPbMax","P/B maximum")}
 if(c.peMin!==null&&c.peMax!==null&&c.peMin>c.peMax)errs.push("P/E: the minimum is higher than the maximum.");
 if(c.pbMin!==null&&c.pbMax!==null&&c.pbMin>c.pbMax)errs.push("P/B: the minimum is higher than the maximum.");
 const roe=+((fel("roe")||{}).value);c.roe=isFinite(roe)&&roe>0?roe:null;
 c.sector=String((fel("fsSector")||{}).value||"");
 c.errors=errs;
 c.active=c.peMode!=="any"||c.peMin!==null||c.peMax!==null||c.pbMode!=="any"||c.pbMin!==null||c.pbMax!==null||c.roe!==null||c.sector!=="";
 return c}
function passes(x,c){if(!x)return false;
 if(c.peMode==="negative"){if(!(isNum(x.pe)&&x.pe<0))return false}
 else if(c.peMode==="positive"||c.peMin!==null||c.peMax!==null){if(!(isNum(x.pe)&&x.pe>0))return false;if(c.peMin!==null&&x.pe<c.peMin)return false;if(c.peMax!==null&&x.pe>c.peMax)return false}
 if(c.pbMode==="negative"){if(!(isNum(x.pb)&&x.pb<0))return false}
 else if(c.pbMode==="positive"||c.pbMin!==null||c.pbMax!==null){if(!(isNum(x.pb)&&x.pb>0))return false;if(c.pbMin!==null&&x.pb<c.pbMin)return false;if(c.pbMax!==null&&x.pb>c.pbMax)return false}
 if(c.roe!==null&&!(isNum(x.roe)&&x.roe>=c.roe&&!froeBad(x)))return false;
 if(c.sector!==""&&!(typeof x.sector==="string"&&x.sector===c.sector))return false;
 return true}
function fcmp(a,c){const k=fsort.k,A=fval(a,k),B=fval(c,k);
 if(TEXTK[k]){const ok1=typeof A==="string"&&A!=="",ok2=typeof B==="string"&&B!=="";if(!ok1&&!ok2)return 0;if(!ok1)return 1;if(!ok2)return -1;return A.localeCompare(B)*fsort.dir}
